// Builds the two files the owner pastes into the LIVE project (ROADMAP S5):
//   supabase/live/live-cutover-bundle.sql  = 000 prepare + migrations 001..006 (one paste, run in the planned window)
//   supabase/live/live-rollback-bundle.sql = puts the old (legacy) behaviour back so the previous app version works again
// Usage: node tools/build-live-bundle.js      (tests/static-checks.js fails if the generated files are out of date)
const fs = require('fs'), path = require('path');
const ROOT = path.resolve(__dirname, '..');
const read = f => fs.readFileSync(path.join(ROOT, 'supabase', f), 'utf8').replace(/\r\n/g, '\n');

function cutover() {
  const parts = ['live/000_prepare_live.sql', 'live/000b_cleanup_live.sql', 'migrations/001_security_foundation.sql', 'migrations/002_auth_login.sql', 'migrations/003_lop_labor_fk.sql',
                 'migrations/004_terminal.sql', 'migrations/005_terminal_least_privilege.sql', 'migrations/006_private_photos.sql'];
  return `-- ============================================================
-- LIVE CUTOVER BUNDLE (generated by tools/build-live-bundle.js - do not edit by hand)
-- Run ONLY on the LIVE project (address contains kyktwzwiraipwyglkhva), ONLY in the planned window, AFTER the preparation steps in
-- supabase/CUTOVER_PLAN.md (Auth accounts created). It moves the other apps' tables to the schema "archive_other_apps" (nothing is deleted),
-- deletes AE2/AE3, unused punch locations and retired supervisors (cleanup, NOT undone by the rollback), applies all security rules, makes the photo bucket private.
-- Rollback: supabase/live/live-rollback-bundle.sql
-- ============================================================

` + parts.map(f => `-- >>>>>>>>>> ${f}\n` + read(f)).join('\n');
}

function rollback() {
  const schema = read('schema.sql');
  const a = schema.indexOf('-- ---------- functions ----------'), b = schema.indexOf('-- ---------- triggers ----------');
  const functions = schema.slice(a, b);
  return `-- ============================================================
-- LIVE ROLLBACK BUNDLE (generated by tools/build-live-bundle.js - do not edit by hand)
-- Puts the OLD behaviour back so the previous app version (old login, public key access, public photos) works again.
-- Use only if the cutover has to be undone. Nothing is deleted: tables moved to archive_other_apps are moved back, supervisors get their old status.
-- After running it: revert the app switch (bump the version) so the site uses the old login again.
-- ============================================================

-- 1. new rules out
do $$
declare r record;
begin
    for r in select schemaname, tablename, policyname from pg_policies where schemaname = 'public' loop
        execute format('drop policy %I on %I.%I', r.policyname, r.schemaname, r.tablename);
    end loop;
    for r in select policyname from pg_policies where schemaname = 'storage' and tablename = 'objects' loop
        execute format('drop policy %I on storage.objects', r.policyname);
    end loop;
end $$;

-- 2. the old open access (as it was before the cutover): rules "allow all" on the tables that had security on, no security on users / clients / labor_id_sequence
do $$
declare t text;
begin
    foreach t in array array['departments','settings','punch_locations','laborers','punch_records','daily_attendance','iqama_registry','lop_requests',
                             'audit_log','enrollment_links','attendance_freeze','holidays','ot_rates','overtime_records'] loop
        execute format('alter table public.%I enable row level security', t);
        execute format('create policy %I on public.%I for all to anon, authenticated using (true) with check (true)', 'Allow all on ' || t, t);
    end loop;
    foreach t in array array['users','clients','labor_id_sequence'] loop
        execute format('alter table public.%I disable row level security', t);
    end loop;
    grant usage on schema public to anon, authenticated;
    grant all on all tables in schema public to anon, authenticated;
    grant all on all sequences in schema public to anon, authenticated;
    grant execute on all functions in schema public to anon, authenticated;
end $$;
alter table public.users alter column password_hash set not null;

-- 3. the old database functions (original bodies)
` + functions + `
grant execute on function public.get_next_labor_id(), public.register_iqama(text), public.update_daily_attendance(text, date) to anon, authenticated;

-- 4. photos public again, old storage rules
update storage.buckets set public = true, file_size_limit = null, allowed_mime_types = null where id = 'punch-photos';
create policy "Allow upload" on storage.objects for insert to anon with check (bucket_id = 'punch-photos');
create policy "Allow view" on storage.objects for select to anon using (bucket_id = 'punch-photos');
create policy "Allow delete" on storage.objects for delete to anon using (bucket_id = 'punch-photos');

-- 5. other apps back, supervisors as before
do $$
declare r record;
begin
    for r in select table_name from information_schema.tables where table_schema = 'archive_other_apps' and table_type = 'BASE TABLE' and table_name <> 'supervisor_status_backup' loop
        execute format('alter table archive_other_apps.%I set schema public', r.table_name);
    end loop;
end $$;
grant all on all tables in schema public to anon, authenticated;
update public.users u set status = b.status from archive_other_apps.supervisor_status_backup b where b.id = u.id;
`;
}
module.exports = { cutover, rollback };
if (require.main === module) {
  fs.writeFileSync(path.join(ROOT, 'supabase/live/live-cutover-bundle.sql'), cutover());
  fs.writeFileSync(path.join(ROOT, 'supabase/live/live-rollback-bundle.sql'), rollback());
  console.log('Wrote supabase/live/live-cutover-bundle.sql and supabase/live/live-rollback-bundle.sql');
}
